/* Compute the discrete fourier transform of x. Store the result in output.
   Example:

   input: [1, 4, 9, 16]
   output: [30+0i, -8-12i, -10-0i, -8+12i]
*/
void fft(std::vector<double> const& x, std::vector<std::complex<double>> &output) {
   int N = x.size();
   output.resize(N, std::complex<double>(0, 0)); // Resize the output vector and initialize with 0

   // Base case: if the input vector has only one element, return it
   if (N == 1) {
      output[0] = x[0];
      return;
   }

   // Divide the input vector into two halves
   std::vector<double> even(N / 2);
   std::vector<double> odd(N / 2);
   for (int i = 0; i < N; i += 2) {
      even[i / 2] = x[i];
      odd[i / 2] = x[i + 1];
   }

   // Recursively compute the FFT of the even and odd halves
   std::vector<std::complex<double>> even_fft(N / 2);
   std::vector<std::complex<double>> odd_fft(N / 2);
   fft(even, even_fft);
   fft(odd, odd_fft);

   // Combine the results
   for (int k = 0; k < N / 2; k++) {
      std::complex<double> t = std::polar(1.0, -2 * M_PI * k / N) * odd_fft[k];
      output[k] = even_fft[k] + t;
      output[k + N / 2] = even_fft[k] - t;
   }
}

