double closestPairRec(std::vector<Point> const& points, int left, int right) {
    // Base case: if there are only two points, return the distance between them
    if (right - left <= 2) {
        double minDist = std::numeric_limits<double>::max();
        for (int i = left; i < right; i++) {
            for (int j = i + 1; j <= right; j++) {
                minDist = std::min(minDist, distance(points[i], points[j]));
            }
        }
        return minDist;
    }

    // Divide the points into two halves
    int mid = (left + right) / 2;
    double dl = closestPairRec(points, left, mid);
    double dr = closestPairRec(points, mid + 1, right);
    double d = std::min(dl, dr);

    // Find the closest pair among the points in the middle strip
    std::vector<Point> strip;
    for (int i = left; i <= right; i++) {
        if (std::abs(points[i].x - points[mid].x) < d) {
            strip.push_back(points[i]);
        }
    }

    // Sort the points in the strip by y-coordinate
    std::sort(strip.begin(), strip.end(), [](Point const& a, Point const& b) {
        return a.y < b.y;
    });

    // Find the closest pair among the points in the strip
    for (size_t i = 0; i < strip.size(); i++) {
        for (size_t j = i + 1; j < strip.size() && (strip[j].y - strip[i].y) < d; j++) {
            d = std::min(d, distance(strip[i], strip[j]));
        }
    }

    return d;
}

