double closestPairUtil(std::vector<Point> const& points, int low, int high) {
    // If there are 2 or 3 points, then use brute force
    if (high - low <= 2) {
        double minDist = std::numeric_limits<double>::max();
        for (int i = low; i < high; i++) {
            for (int j = i + 1; j <= high; j++) {
                const double dist = distance(points[i], points[j]);
                if (dist < minDist) {
                    minDist = dist;
                }
            }
        }
        return minDist;
    }

    // Find the middle point
    int mid = (low + high) / 2;
    Point midPoint = points[mid];

    // Find the smallest distance in the left and right halves
    double dl = closestPairUtil(points, low, mid);
    double dr = closestPairUtil(points, mid + 1, high);

    // Find the smallest distance between the left and right halves
    double d = std::min(dl, dr);

    // Create an array strip[] that contains points close to the middle line
    std::vector<Point> strip;
    for (int i = low; i <= high; i++) {
        if (std::abs(points[i].x - midPoint.x) < d) {
            strip.push_back(points[i]);
        }
    }

    // Find the smallest distance in the strip
