void convolveKernel(std::vector<int> const& imageIn, std::vector<int> &imageOut, size_t N) {
    std::transform(imageIn.begin(), imageIn.end(), imageOut.begin(), [&](int pixel) {
        int sum = 0;
        for (int k = -1; k < 2; k++) {
            for (int l = -1; l < 2; l++){
                int x = pixel / N + k;
                int y = pixel % N + l;
                if ((x < 0) || (x >= N) || (y < 0) || (y >= N)) {
                    sum += 0;
