   std::vector<double> A_copy = A;
   std::vector<double> b_copy = b;

   // LU decomposition
   for (size_t i = 0; i < N - 1; i++) {
      // Find the pivot element
      double pivot = A_copy[i * N + i];

      // Check if the pivot is zero
      if (pivot == 0) {
         return;
      }

      // Eliminate the elements below the pivot
      for (size_t j = i + 1; j < N; j++) {
         double factor = A_copy[j * N + i] / pivot;
         for (size_t k = i; k < N; k++) {
            A_copy[j * N + k] -= factor * A_copy[i * N + k];
         }
         b_copy[j] -= factor * b_copy[i];
      }
   }

   // Thomas algorithm for back substitution
   std::vector<double> c(N), d(N);
   c[0] = A_copy[0 * N + 0];
   d[0] = b_copy[0];
   for (size_t i = 1; i < N; i++) {
      c[i] = A_copy[i * N + i] - A_copy[i * N + i - 1] * A_copy[(i - 1) * N + i] / c[i - 1];
      d[i] = b_copy[i] - A_copy[i * N + i - 1] * d[i - 1] / c[i - 1];
   }
   x[N - 1] = d[N - 1] / c[N - 1];
   for (int i = N - 2; i >= 0; i--) {
      x[i] = (d[i] - A_copy[i * N + i + 1] * x[i + 1]) / c[i];
   }
